def number_what_is_there(apps, schema_editor):
    """Topics get their short code; questions keep the order they were shown in (oldest first) as their position."""
    from apps.productivity.models import topic_code

    PrepTopic, Question = apps.get_model("productivity", "PrepTopic"), apps.get_model("productivity", "Question")
    for t in PrepTopic.objects.all():
        t.code = topic_code(t.name).upper()
        t.save(update_fields=["code"])
        for i, q in enumerate(Question.objects.filter(topic=t).order_by("difficulty", "pk").only("pk"), 1):
            Question.objects.filter(pk=q.pk).update(order=i)


